// SPDX-License-Identifier: MIT
// Own finite control: no tokens, addresses, external calls or funds.
pragma solidity 0.8.30;
contract StatefulConservation {
 uint16 private debit = 15;
 uint16 private credit = 0;
 uint8 private steps = 0;
 function move(uint8 quantity) public {
  require(steps < 3 && quantity <= debit);
  debit -= quantity;
  credit += uint16(quantity) + (steps == 2 ? 0 : 0);
  steps++;
  assert(steps != 3);
 }
}

